def parallel_sum(xs, workers):
    if workers == 0:
        raise ValueError('NoWorkers')
    chunk = -(-len(xs) // workers)
    return sum(sum(xs[i * chunk:(i + 1) * chunk]) for i in range(workers))

assert parallel_sum(list(range(1, 1001)), 4) == 500500
assert parallel_sum([], 3) == 0

