    var xs: [1000]i64 = undefined;
    for (&xs, 0..) |*x, i| x.* = @intCast(i + 1);
    try std.testing.expectEqual(@as(i64, 500500), try parallelSum(std.testing.allocator, std.testing.io, &xs, 4));
    try std.testing.expectEqual(@as(i64, 500500), try parallelSum(std.testing.allocator, std.testing.io, &xs, 7));
    try std.testing.expectEqual(@as(i64, 0), try parallelSum(std.testing.allocator, std.testing.io, xs[0..0], 3));
